var VELOCIDAD = 1.5;
var LARGO_PISTA = 12;
var RADIO = { Wheel_FR: 0.3153, Wheel_FL: 0.3153, Wheel_BR: 0.3399, Wheel_BL: 0.3399 };

var encendido = false;
var ruedas = [];
var faros = [];
var boton;

function init() {

	for ( var nombre in RADIO ) {

		var llanta = this.getObjectByName( nombre );
		if ( llanta ) ruedas.push( { objeto: llanta, radio: RADIO[ nombre ] } );

	}

	this.traverse( function ( pieza ) {

		if ( pieza.material === undefined ) return;

		if ( pieza.material.name === 'Headlight_light' ||
		     pieza.material.name === 'Headlight_ligh_second' ||
		     pieza.material.name === 'Light' ) {

			faros.push( pieza.material );

		}

	} );

	boton = document.createElement( 'button' );
	boton.textContent = 'Encender auto';
	boton.style.position = 'absolute';
	boton.style.top = '20px';
	boton.style.left = '20px';
	boton.style.padding = '12px 20px';
	boton.style.fontSize = '16px';
	boton.style.cursor = 'pointer';
	document.body.appendChild( boton );

	boton.addEventListener( 'click', function () {

		encendido = ! encendido;
		boton.textContent = encendido ? 'Apagar auto' : 'Encender auto';

	} );

}

function update( event ) {

	var dt = event.delta / 1000;

	for ( var i = 0; i < faros.length; i ++ ) {

		faros[ i ].emissive.setHex( 0xfff4e0 );
		faros[ i ].emissiveIntensity = encendido ? 10 : 0;

	}

	if ( encendido === false ) return;

	this.position.z += VELOCIDAD * dt;
	if ( this.position.z > LARGO_PISTA ) this.position.z -= LARGO_PISTA * 2;

	for ( var j = 0; j < ruedas.length; j ++ ) {

		ruedas[ j ].objeto.rotateY( ( VELOCIDAD / ruedas[ j ].radio ) * dt );

	}

}

function stop() {

	if ( boton ) boton.remove();

}
